(()=> {
const pack = {"male":[{"key":"coach-m-tracksuit","label":"Trainingsanzug","src":"data:image/webp;base64,"},{"key":"coach-m-turtleneck","label":"Rollkragen","src":"data:image/webp;base64,"},{"key":"coach-m-polo","label":"Polo","src":"data:image/webp;base64,"},{"key":"coach-m-suit-tie","label":"Anzug & Krawatte","src":"data:image/webp;base64,"},{"key":"coach-m-suit-open","label":"Anzug offen","src":"data:image/webp;base64,"},{"key":"coach-m-overcoat","label":"Mantel & Pullover","src":"data:image/webp;base64,"}],"female":[{"key":"coach-f-closed-suit","label":"Business geschlossen","src":"data:image/webp;base64,"},{"key":"coach-f-skirt-blazer","label":"Long-Blazer & Rock","src":"data:image/webp;base64,"},{"key":"coach-f-dark-suit-neckline","label":"Hosenanzug dunkel","src":"data:image/webp;base64,"},{"key":"coach-f-taupe-suit-neckline","label":"Hosenanzug Taupe","src":"data:image/webp;base64,"},{"key":"coach-f-tracksuit","label":"Trainingsanzug","src":"data:image/webp;base64,"},{"key":"coach-f-polo","label":"Polo","src":"data:image/webp;base64,"}]};
// Correct two source assets that were assigned to the wrong gender group.
const wrongMaleIndex = pack.male.findIndex(x => x.key === "coach-m-suit-open");
const wrongFemaleIndex = pack.female.findIndex(x => x.key === "coach-f-closed-suit");
if (wrongMaleIndex >= 0 && wrongFemaleIndex >= 0) {
  const maleBody = pack.female[wrongFemaleIndex];
  const femaleBody = pack.male[wrongMaleIndex];
  pack.male[wrongMaleIndex] = maleBody;
  pack.female[wrongFemaleIndex] = femaleBody;
}
window.TimeClashTrainerBodies = pack;
window.TimeClashTrainerBodiesByKey = Object.fromEntries(
  [...pack.male, ...pack.female].map(x => [x.key, x])
);
})();